import {
    flexRender,
    getCoreRowModel,
    useReactTable,
} from '@tanstack/react-table';
import type {
    ColumnDef,
    OnChangeFn,
    Row,
    RowData,
    RowSelectionState,
    SortingState,
} from '@tanstack/react-table';
import { ChevronDown, ChevronRight } from 'lucide-react';
import { Fragment } from 'react';
import type { HTMLAttributes, ReactNode } from 'react';
import { useTranslation } from 'react-i18next';
import {
    TablePaginationFooter,
    TablePanel,
    hasTablePaginationFooter,
} from '@/components/layout/page-layout';
import type { TablePaginationState } from '@/components/layout/page-layout';
import { Button } from '@/components/ui/button';
import { Checkbox } from '@/components/ui/checkbox';
import { Empty, EmptyHeader, EmptyTitle } from '@/components/ui/empty';
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from '@/components/ui/table';
import { cn } from '@/lib/utils';

declare module '@tanstack/react-table' {
    // Type parameters are required by the declaration merge.
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    interface ColumnMeta<TData extends RowData, TValue> {
        /** Classes for the column's `<th>`. */
        headerClassName?: string;
        /** Classes for each of the column's `<td>`. */
        cellClassName?: string;
        /** Clicks inside the cell do not reach `onRowClick` (checkboxes, row actions). */
        isRowClickIgnored?: boolean;
    }
}

/** Server sort state: the sorted column id and its direction. */
export type DataTableSort = {
    id: string;
    direction: 'asc' | 'desc';
};

export type DataTableProps<TData> = {
    /** Column definitions; a sortable column needs `accessorKey` / `accessorFn` and `enableSorting: true`, and its id is the server sort field. */
    columns: ColumnDef<TData, unknown>[];
    data: TData[];
    /** Stable row id (the record key); row selection is keyed by it. */
    getRowId: (row: TData) => string;
    /** Current server sort; omit for a list without column sorting. */
    sort?: DataTableSort;
    /** Called with the new sort when a column header asks for one. */
    onSortChange?: (sort: DataTableSort) => void;
    /** Controlled row selection (`{ [rowId]: true }`); omit to disable selection. */
    rowSelection?: RowSelectionState;
    onRowSelectionChange?: OnChangeFn<RowSelectionState>;
    /** Server paginator; renders the shared pagination footer when it is needed. */
    pagination?: TablePaginationState;
    /** Opens a row (edit drawer, detail page). */
    onRowClick?: (row: TData) => void;
    /** Extra props per `<tr>` (`data-test`, classes). */
    getRowProps?: (row: TData) => HTMLAttributes<HTMLTableRowElement> & {
        [dataAttribute: `data-${string}`]: string | undefined;
    };
    /** Details shown in a full-width row under an expanded row (see {@link dataTableExpandColumn}). */
    renderExpandedRow?: (row: TData) => ReactNode;
    /** Shown in the table body when `data` is empty. */
    emptyState?: ReactNode;
    className?: string;
};

/**
 * Server-driven data table: the shadcn data-table pattern on TanStack Table,
 * with sorting, pagination and filtering done by the server (`manual*`). The
 * page owns the query (Inertia visits, URL params, `per_page`); the table
 * renders the rows, reports header sort and selection changes, and puts the
 * shared pagination footer under the rows inside a `TablePanel`.
 *
 * Generic on purpose: no app types here, so it can become a registry item.
 *
 * @param props - See {@link DataTableProps}.
 * @returns {JSX.Element}
 */
export function DataTable<TData>({
    columns,
    data,
    getRowId,
    sort,
    onSortChange,
    rowSelection,
    onRowSelectionChange,
    pagination,
    onRowClick,
    getRowProps,
    renderExpandedRow,
    emptyState,
    className,
}: DataTableProps<TData>) {
    const { t } = useTranslation();
    const sorting: SortingState = sort
        ? [{ id: sort.id, desc: sort.direction === 'desc' }]
        : [];

    const handleSortingChange: OnChangeFn<SortingState> = (updater) => {
        const nextSorting =
            typeof updater === 'function' ? updater(sorting) : updater;
        const [nextSort] = nextSorting;

        if (!nextSort || !onSortChange) {
            return;
        }

        onSortChange({
            id: nextSort.id,
            direction: nextSort.desc ? 'desc' : 'asc',
        });
    };

    // TanStack Table returns fresh functions every render, so the React
    // Compiler skips this component; that is the documented trade-off.
    // eslint-disable-next-line react-hooks/incompatible-library
    const table = useReactTable({
        data,
        columns,
        getRowId,
        getCoreRowModel: getCoreRowModel(),
        manualSorting: true,
        manualPagination: true,
        manualFiltering: true,
        enableSortingRemoval: false,
        enableRowSelection: rowSelection !== undefined,
        getRowCanExpand: () => renderExpandedRow !== undefined,
        defaultColumn: { enableSorting: false },
        pageCount: pagination?.last_page ?? 1,
        state: {
            sorting,
            rowSelection: rowSelection ?? {},
        },
        onSortingChange: handleSortingChange,
        onRowSelectionChange,
    });

    const handleRowClick = (row: Row<TData>): void => {
        onRowClick?.(row.original);
    };

    return (
        <TablePanel
            className={className}
            footer={
                pagination && hasTablePaginationFooter(pagination) ? (
                    <TablePaginationFooter pagination={pagination} />
                ) : undefined
            }
        >
            <Table>
                <TableHeader>
                    {table.getHeaderGroups().map((headerGroup) => (
                        <TableRow key={headerGroup.id}>
                            {headerGroup.headers.map((header) => (
                                <TableHead
                                    key={header.id}
                                    colSpan={header.colSpan}
                                    className={
                                        header.column.columnDef.meta
                                            ?.headerClassName
                                    }
                                >
                                    {header.isPlaceholder
                                        ? null
                                        : flexRender(
                                              header.column.columnDef.header,
                                              header.getContext(),
                                          )}
                                </TableHead>
                            ))}
                        </TableRow>
                    ))}
                </TableHeader>
                <TableBody>
                    {table.getRowModel().rows.length > 0 ? (
                        table.getRowModel().rows.map((row) => {
                            const rowProps = getRowProps?.(row.original);

                            return (
                                <Fragment key={row.id}>
                                    <TableRow
                                        data-state={
                                            row.getIsSelected()
                                                ? 'selected'
                                                : undefined
                                        }
                                        {...rowProps}
                                        className={cn(
                                            onRowClick && 'cursor-pointer',
                                            rowProps?.className,
                                        )}
                                        onClick={
                                            onRowClick
                                                ? () => handleRowClick(row)
                                                : undefined
                                        }
                                    >
                                        {row.getVisibleCells().map((cell) => {
                                            const meta =
                                                cell.column.columnDef.meta;

                                            return (
                                                <TableCell
                                                    key={cell.id}
                                                    className={
                                                        meta?.cellClassName
                                                    }
                                                    onClick={
                                                        meta?.isRowClickIgnored
                                                            ? (event) =>
                                                                  event.stopPropagation()
                                                            : undefined
                                                    }
                                                >
                                                    {flexRender(
                                                        cell.column.columnDef
                                                            .cell,
                                                        cell.getContext(),
                                                    )}
                                                </TableCell>
                                            );
                                        })}
                                    </TableRow>
                                    {row.getIsExpanded() &&
                                    renderExpandedRow ? (
                                        <TableRow className="hover:bg-transparent">
                                            <TableCell
                                                colSpan={
                                                    row.getVisibleCells().length
                                                }
                                            >
                                                {renderExpandedRow(
                                                    row.original,
                                                )}
                                            </TableCell>
                                        </TableRow>
                                    ) : null}
                                </Fragment>
                            );
                        })
                    ) : (
                        <TableRow className="hover:bg-transparent">
                            <TableCell colSpan={columns.length}>
                                {emptyState ?? (
                                    <Empty className="p-6 md:p-6">
                                        <EmptyHeader>
                                            <EmptyTitle className="text-sm font-normal text-muted-foreground">
                                                {t('common.noResults')}
                                            </EmptyTitle>
                                        </EmptyHeader>
                                    </Empty>
                                )}
                            </TableCell>
                        </TableRow>
                    )}
                </TableBody>
            </Table>
        </TablePanel>
    );
}

/**
 * The selection column of the shadcn data-table pattern: a select-all
 * checkbox in the header and one checkbox per row. Clicks on it never open
 * the row.
 *
 * @param options.selectAllLabel - Accessible name of the header checkbox.
 * @param options.getRowLabel - Accessible name of a row checkbox.
 * @returns {ColumnDef<TData, unknown>}
 */
export function dataTableSelectColumn<TData>({
    selectAllLabel,
    getRowLabel,
}: {
    selectAllLabel: string;
    getRowLabel: (row: TData) => string;
}): ColumnDef<TData, unknown> {
    return {
        id: 'select',
        meta: { headerClassName: 'w-10', isRowClickIgnored: true },
        header: ({ table }) => (
            <Checkbox
                checked={
                    table.getIsAllPageRowsSelected() ||
                    (table.getIsSomePageRowsSelected() && 'indeterminate')
                }
                onCheckedChange={(checked) =>
                    table.toggleAllPageRowsSelected(checked === true)
                }
                aria-label={selectAllLabel}
            />
        ),
        cell: ({ row }) => (
            <Checkbox
                checked={row.getIsSelected()}
                onCheckedChange={(checked) =>
                    row.toggleSelected(checked === true)
                }
                aria-label={getRowLabel(row.original)}
            />
        ),
    };
}

/**
 * Expand toggle column for a {@link DataTable} with `renderExpandedRow`.
 *
 * @param options.expandLabel - Accessible name while collapsed.
 * @param options.collapseLabel - Accessible name while expanded.
 * @returns {ColumnDef<TData, unknown>}
 */
export function dataTableExpandColumn<TData>({
    expandLabel,
    collapseLabel,
}: {
    expandLabel: string;
    collapseLabel: string;
}): ColumnDef<TData, unknown> {
    return {
        id: 'expand',
        meta: { headerClassName: 'w-8', isRowClickIgnored: true },
        header: () => null,
        cell: ({ row }) => {
            const isExpanded = row.getIsExpanded();

            return (
                <Button
                    type="button"
                    variant="ghost"
                    size="icon-sm"
                    className="text-muted-foreground"
                    aria-expanded={isExpanded}
                    aria-label={isExpanded ? collapseLabel : expandLabel}
                    onClick={row.getToggleExpandedHandler()}
                >
                    {isExpanded ? (
                        <ChevronDown aria-hidden="true" />
                    ) : (
                        <ChevronRight aria-hidden="true" />
                    )}
                </Button>
            );
        },
    };
}

import type { Column } from '@tanstack/react-table';
import { ArrowDown, ArrowUp, ChevronsUpDown } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { Button } from '@/components/ui/button';
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { cn } from '@/lib/utils';

/**
 * Column header of the shadcn data-table pattern: a sortable column opens a
 * dropdown with ascending / descending; any other column renders its title.
 * With a server-driven {@link DataTable} the choice becomes a new server sort.
 *
 * @param props.column - TanStack column.
 * @param props.title - Visible header text.
 * @returns {JSX.Element}
 */
export function DataTableColumnHeader<TData, TValue>({
    column,
    title,
    className,
}: {
    column: Column<TData, TValue>;
    title: string;
    className?: string;
}) {
    const { t } = useTranslation();

    if (!column.getCanSort()) {
        return <div className={className}>{title}</div>;
    }

    const sortDirection = column.getIsSorted();

    return (
        <div className={cn('flex items-center', className)}>
            <DropdownMenu>
                <DropdownMenuTrigger asChild>
                    <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        className="-ml-2 text-sm data-[state=open]:bg-accent"
                        data-test={`column-sort-${column.id}`}
                    >
                        <span>{title}</span>
                        {sortDirection === 'desc' ? (
                            <ArrowDown aria-hidden="true" />
                        ) : sortDirection === 'asc' ? (
                            <ArrowUp aria-hidden="true" />
                        ) : (
                            <ChevronsUpDown aria-hidden="true" />
                        )}
                    </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="start">
                    <DropdownMenuItem
                        onClick={() => column.toggleSorting(false)}
                    >
                        <ArrowUp aria-hidden="true" />
                        {t('common.sortAscending')}
                    </DropdownMenuItem>
                    <DropdownMenuItem
                        onClick={() => column.toggleSorting(true)}
                    >
                        <ArrowDown aria-hidden="true" />
                        {t('common.sortDescending')}
                    </DropdownMenuItem>
                </DropdownMenuContent>
            </DropdownMenu>
        </div>
    );
}

import { Check, PlusCircle } from 'lucide-react';
import type { ComponentType } from 'react';
import { useTranslation } from 'react-i18next';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import {
    Command,
    CommandEmpty,
    CommandGroup,
    CommandInput,
    CommandItem,
    CommandList,
    CommandSeparator,
} from '@/components/ui/command';
import {
    Popover,
    PopoverContent,
    PopoverTrigger,
} from '@/components/ui/popover';
import { Separator } from '@/components/ui/separator';
import { cn } from '@/lib/utils';

export type DataTableFacetedFilterOption = {
    value: string;
    label: string;
    icon?: ComponentType<{ className?: string }>;
};

export type DataTableFacetedFilterProps = {
    /** Visible trigger text (the facet: "Action", "Status"). */
    title: string;
    options: DataTableFacetedFilterOption[];
    /** Values currently applied on the server. */
    selectedValues: string[];
    onSelectedValuesChange: (values: string[]) => void;
    /** `false` keeps one value at a time (the server filters on one). */
    isMultiple?: boolean;
    /** Accessible name of the trigger, when it should differ from `title`. */
    ariaLabel?: string;
    className?: string;
};

/**
 * Faceted filter of the shadcn data-table pattern: an outline trigger with the
 * selected values as badges, opening a searchable `Command` list in a
 * `Popover`. Server-driven: the page turns the new values into a visit.
 *
 * @param props - See {@link DataTableFacetedFilterProps}.
 * @returns {JSX.Element}
 */
export function DataTableFacetedFilter({
    title,
    options,
    selectedValues,
    onSelectedValuesChange,
    isMultiple = true,
    ariaLabel,
    className,
}: DataTableFacetedFilterProps) {
    const { t } = useTranslation();
    const selected = new Set(selectedValues);

    const toggleValue = (value: string): void => {
        if (!isMultiple) {
            onSelectedValuesChange(selected.has(value) ? [] : [value]);

            return;
        }

        onSelectedValuesChange(
            selected.has(value)
                ? selectedValues.filter((current) => current !== value)
                : [...selectedValues, value],
        );
    };

    return (
        <Popover>
            <PopoverTrigger asChild>
                <Button
                    type="button"
                    variant="outline"
                    aria-label={ariaLabel}
                    className={cn('justify-start border-dashed', className)}
                >
                    <PlusCircle aria-hidden="true" />
                    {title}
                    {selected.size > 0 ? (
                        <>
                            <Separator
                                orientation="vertical"
                                className="mx-0.5 data-[orientation=vertical]:h-4"
                            />
                            <Badge
                                variant="secondary"
                                className="rounded-sm px-1 font-normal lg:hidden"
                            >
                                {selected.size}
                            </Badge>
                            <div className="hidden min-w-0 gap-1 lg:flex">
                                {selected.size > 2 ? (
                                    <Badge
                                        variant="secondary"
                                        className="rounded-sm px-1 font-normal"
                                    >
                                        {t('common.selectedCount', {
                                            count: selected.size,
                                        })}
                                    </Badge>
                                ) : (
                                    options
                                        .filter((option) =>
                                            selected.has(option.value),
                                        )
                                        .map((option) => (
                                            <Badge
                                                key={option.value}
                                                variant="secondary"
                                                className="truncate rounded-sm px-1 font-normal"
                                            >
                                                {option.label}
                                            </Badge>
                                        ))
                                )}
                            </div>
                        </>
                    ) : null}
                </Button>
            </PopoverTrigger>
            <PopoverContent className="w-[12.5rem] p-0" align="start">
                <Command>
                    <CommandInput placeholder={title} />
                    <CommandList>
                        <CommandEmpty>{t('common.noResults')}</CommandEmpty>
                        <CommandGroup>
                            {options.map((option) => {
                                const isSelected = selected.has(option.value);

                                return (
                                    <CommandItem
                                        key={option.value}
                                        value={option.label}
                                        onSelect={() =>
                                            toggleValue(option.value)
                                        }
                                    >
                                        <div
                                            className={cn(
                                                'flex size-4 items-center justify-center rounded-[4px] border',
                                                isSelected
                                                    ? 'border-primary bg-primary text-primary-foreground'
                                                    : 'border-input [&_svg]:invisible',
                                            )}
                                        >
                                            <Check
                                                className="size-3.5 text-primary-foreground"
                                                aria-hidden="true"
                                            />
                                        </div>
                                        {option.icon ? (
                                            <option.icon className="size-4 text-muted-foreground" />
                                        ) : null}
                                        <span>{option.label}</span>
                                    </CommandItem>
                                );
                            })}
                        </CommandGroup>
                        {selected.size > 0 ? (
                            <>
                                <CommandSeparator />
                                <CommandGroup>
                                    <CommandItem
                                        onSelect={() =>
                                            onSelectedValuesChange([])
                                        }
                                        className="justify-center text-center"
                                    >
                                        {t('common.clearFilters')}
                                    </CommandItem>
                                </CommandGroup>
                            </>
                        ) : null}
                    </CommandList>
                </Command>
            </PopoverContent>
        </Popover>
    );
}
